def _center_lift_int(a, q):
    """Return the centered representative of a modulo q in (-q/2,q/2]."""
    a = int(a) % int(q)
    if a > int(q)//_sage_const_2 :
        a -= int(q)
    return a


def _center_lift_poly_from_q0(poly_q0):
    """Interpret a q0-share polynomial as an integer polynomial."""
    coeffs = _dense_coeffs(poly_q0, POLDEG)
    return R([_center_lift_int(c, q_list[_sage_const_0 ]) for c in coeffs])


def _shares_from_center_lift_q0(poly_q0, active=L):
    """Create q0..q_{active-1} shares from centered q0 representatives."""
    z = _center_lift_poly_from_q0(poly_q0)
    return [poly_mod_prime(z, q_list[j]) for j in range(active)]


def toy_modraise_q0_to_full(ct_q0, active=L):
    """Toy q0 -> Q materialization for a ciphertext.

    Input ct_q0 must have exactly one q-share per component.  Output has
    active q-shares per component.  This preserves the q0 share exactly and
    makes every other share a coefficient-wise centered lift of that q0 share.
    """
    if len(ct_q0[_sage_const_0 ]) != _sage_const_1 :
        raise ValueError("toy_modraise_q0_to_full expects a q0-only ciphertext")

    c0_full = _shares_from_center_lift_q0(ct_q0[_sage_const_0 ][_sage_const_0 ], active)
    c1_full = []
    for comp in ct_q0[_sage_const_1 ]:
        if len(comp) != _sage_const_1 :
            raise ValueError("toy_modraise_q0_to_full expects q0-only c1 components")
        c1_full.append(_shares_from_center_lift_q0(comp[_sage_const_0 ], active))
    return [c0_full, c1_full]


def client_encrypt_q0(m_plain, key):
    """Actual client-side low-rank, q0-only encryption.

    This computes only the q0 residue of ModHE encryption.  It intentionally
    avoids constructing the full Q ciphertext, so it models the desired client
    optimization more faithfully than encrypting at Q and slicing q0.
    """
    rank = key[_sage_const_0 ].ncols()

    e0 = random_poly_error()
    e1 = matrix(R, _sage_const_1 , rank)
    v = matrix(R, _sage_const_1 , rank)
    for k in range(rank):
        e1[_sage_const_0 , k] = random_poly_error()
        v[_sage_const_0 , k] = random_poly_sparse_binary()

    m_enc = round(m_plain*p_enc)
    b_pk = key[_sage_const_1 ]
    A = key[_sage_const_2 ]

    temp0 = (v*b_pk + m_enc + e0) % firreducible
    c0_q0 = poly_mod_prime(temp0[_sage_const_0 , _sage_const_0 ], q_list[_sage_const_0 ])

    temp1 = (v*A + e1) % firreducible
    c1_q0 = [[poly_mod_prime(temp1[_sage_const_0 , k], q_list[_sage_const_0 ])] for k in range(rank)]

    return [[c0_q0], c1_q0]


def ct_shape(ct):
    return (len(ct[_sage_const_1 ]), len(ct[_sage_const_0 ]))  # (rank, active q-shares)


def check_close(label, got, expected, tol=_sage_const_1en5 ):
    diff = abs(float(got) - float(expected))
    print(label, "=", got, " expected=", expected, " diff=", diff)
    if diff > tol:
        print("WARNING:", label, "diff exceeds tolerance", tol)
    return diff


